<?php
if (!defined('ABSPATH')) exit;
final class KCB_Field_Mapper {
 const FIELDS=['customer_name','mobile','email','message','consent','external_id'];
 const ALIASES=['customer_name'=>['customer_name','name','full_name','your-name'],'mobile'=>['mobile','phone','phone_number','telephone','your-phone'],'email'=>['email','email_address','your-email'],'message'=>['message','notes','enquiry','your-message'],'consent'=>['consent','permission','opt_in'],'external_id'=>['external_id','lead_id','submission_id']];
 static function path($object,$path,&$found=null){$found=false;if(!is_string($path)||strlen($path)>180||!preg_match('/^[A-Za-z0-9_-]+(?:\.[A-Za-z0-9_-]+|\[[0-9]{1,5}\])*$/D',$path))return null;$parts=preg_split('/\.|\[|\]/',$path,-1,PREG_SPLIT_NO_EMPTY);if(count($parts)>20)return null;$node=$object;foreach($parts as $part){if(!is_array($node)||!array_key_exists($part,$node))return null;$node=$node[$part];}$found=true;return $node;}
 static function suggest($sample){$candidates=[];foreach(self::FIELDS as $field){$candidates[$field]=[];foreach(self::ALIASES[$field] as $alias){self::find_alias($sample,$alias,'',$candidates[$field],0);}$candidates[$field]=array_values(array_unique($candidates[$field]));}return $candidates;}
 static function find_alias($obj,$alias,$prefix,&$out,$depth){if($depth>5||!is_array($obj))return;foreach($obj as $key=>$val){$key=(string)$key;$path=$prefix===''?$key:($prefix.(ctype_digit($key)?'['.$key.']':'.'.$key));if(strtolower($key)===strtolower($alias)&&!is_array($val)&&!is_object($val))$out[]=$path;if(is_array($val))self::find_alias($val,$alias,$path,$out,$depth+1);}}
 static function is_list($a){return is_array($a)&&($a===[]||array_keys($a)===range(0,count($a)-1));}
 static function parse($json,$max=262144){if(!is_string($json)||strlen($json)>$max)return new WP_Error('too_large','JSON exceeds the 256 KB size limit.');$value=json_decode($json,true,32);if(json_last_error()!==JSON_ERROR_NONE)return new WP_Error('invalid_json','Malformed JSON: '.json_last_error_msg());if(!is_array($value))return new WP_Error('structure','JSON root must be an object or an explicitly selected array.');return $value;}
 static function extract($data,$array_path){if($array_path===''){if(self::is_list($data))return new WP_Error('array_path','Select an array path explicitly; use $ for a root array.');return [$data];}if($array_path==='$')$items=$data;else{$found=false;$items=self::path($data,$array_path,$found);if(!$found)return new WP_Error('array_path','Selected array path does not exist.');}if(!is_array($items)||!self::is_list($items))return new WP_Error('array_path','Selected path must point to an array of lead objects.');if(count($items)<1||count($items)>100)return new WP_Error('array_size','Lead array must contain between 1 and 100 items.');foreach($items as $i=>$item)if(!is_array($item)||self::is_list($item))return new WP_Error('array_item','Item '.($i+1).' is not a lead object.');return $items;}
 static function normalize($item,$map,$yes){$out=[];$errors=[];foreach(self::FIELDS as $field){$path=$map[$field]??'';if($path==='')continue;$found=false;$value=self::path($item,$path,$found);if(!$found||$value===null||$value==='')continue;if(!is_scalar($value)){$errors[]="$field must be a scalar value.";continue;}$out[$field]=is_bool($value)?($value?'true':'false'):(string)$value;}
 $name=trim($out['customer_name']??'');$mobile=trim($out['mobile']??'');if($name==='')$errors[]='customer_name is required.';if($mobile==='')$errors[]='mobile is required.';elseif(!preg_match('/^\+?[0-9][0-9 ()-]{5,22}$/D',$mobile)||strlen(preg_replace('/\D/','',$mobile))<7||strlen(preg_replace('/\D/','',$mobile))>15)$errors[]='mobile must contain 7–15 digits with an optional country code.';
 if(isset($out['email'])&&$out['email']!==''&&!is_email($out['email']))$errors[]='email is invalid.';
 $consent=false;if(isset($out['consent'])){$raw=strtolower(trim($out['consent']));$consent=in_array($raw,array_map('strtolower',array_map('trim',$yes)),true);}
 if(!$consent)$errors[]='Explicit affirmative contact consent is required.';
 $id=trim($out['external_id']??'');if(strlen($id)>150)$errors[]='external_id is too long.';
 return ['payload'=>['customer_name'=>sanitize_text_field($name),'mobile'=>$mobile,'email'=>sanitize_email($out['email']??''),'message'=>sanitize_textarea_field($out['message']??''),'consent'=>$consent,'external_id'=>$id],'errors'=>$errors];}
 static function mapping($in){$map=[];foreach(self::FIELDS as $field){$p=trim((string)($in[$field]??''));$found=false;self::path([], $p, $found);if($p!==''&&!preg_match('/^[A-Za-z0-9_-]+(?:\.[A-Za-z0-9_-]+|\[[0-9]{1,5}\])*$/D',$p))return new WP_Error('path','Invalid mapping path for '.$field);$map[$field]=$p;}return $map;}
}
